'use strict';
// Four shared play systems replace retired picture-only activations and topic choosers.
const Purposeful=(()=>{
 let timer=null,paused=false,serial=0;
 const q=s=>app.querySelector(s),svg=(b,label)=>readingAdventureSvg(b,label,'0 0 700 400');
 const person=(x,y,kind='duck',action='wave')=>`<svg x="${x}" y="${y}" width="100" height="110" viewBox="0 -20 200 220">${readingAdventureAnimal(kind,action).replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</svg>`;
 function active(s){return senState===s&&!!q('.purposeful-play')&&s.task?.mode==='mission';}
 function can(s){return active(s)&&!s.done&&!paused;}
 function cancel(){if(timer!==null)clearTimeout(timer);timer=null;}
 function init(s){if(s.play)return;cancel();paused=false;s.play={id:s.task.mission,version:++serial,step:0,selected:null,wheels:[false,false],washed:false,paint:'#779cc2',horn:false,destination:null,pipes:[{cell:0,type:'straight',r:1},{cell:1,type:'elbow',r:0},{cell:4,type:'elbow',r:2},{cell:5,type:'straight',r:0}],trace:[],message:''};}
 function change(s,message='',focus){s.play.version=++serial;s.response=message;render(focus);}
 function finish(s,message){if(!can(s))return;s.done=true;s.play.finished=true;s.response=message;s.records=[{round:0,observation:'not-recorded',helpUsed:s.hint,retries:s.retries,kind:'mission',mission:s.play.id,actions:s.play.version}];render();}
 function continueCourse(s){if(!active(s)||!s.done||paused)return;cancel();senFinish();}
 function schedule(s){cancel();if(typeof CourseFlow==='undefined'||!active(s)||!s.done||paused||!CourseFlow.enabled)return;timer=setTimeout(()=>{timer=null;if(active(s)&&!paused)continueCourse(s);},1600);}
 function boat(x,y,boarded){return `<g transform="translate(${x} ${y})">${boarded?person(8,-94):''}<path d="M0 0H122L102 30H24Z" fill="#c17c53" stroke="#78563f" stroke-width="3"/><path d="M0 0H122" stroke="#f4d6a4" stroke-width="8"/><rect x="79" y="-35" width="31" height="28" rx="4" fill="#e5bd7d"/><path d="M94-35V-7" stroke="#af8c58" stroke-width="3"/></g>`;}
 function canal(p){const water=p.step>=2?225:295;return svg(`<rect width="700" height="400" rx="24" fill="#dceef3"/><circle cx="605" cy="54" r="28" fill="#ffe4a0"/><path d="M0 256H210V400H0ZM495 215H700V400H495Z" fill="#a9c899"/><path d="M210 ${water}H495V400H210Z" fill="#80c4d5"/><path d="M495 225H700V400H495Z" fill="#80c4d5"/><path d="M205 253V400M494 214V400" stroke="#b89f7d" stroke-width="15"/><path d="M218 ${water+22}H478M225 ${water+53}H471" stroke="#c0e4e8" stroke-width="4"/>${p.step<3?'<path d="M491 216V392" stroke="#9d7659" stroke-width="15"/>':'<path d="M491 213L457 178" stroke="#9d7659" stroke-width="15"/>'}${p.step===1?'<path d="M130 257L260 289" stroke="#c7a075" stroke-width="14"/>':''}${p.step===0?person(100,153):''}${boat(p.step===3?510:250,water-6,p.step>=1)}<path d="M640 215V159H695V215" fill="#f2dcc1" stroke="#a48b67" stroke-width="4"/><path d="M630 160L667 126L700 160Z" fill="#b68088"/>${p.step===3?'<path d="M562 113l9-10M606 88v-14M660 109l11-8" stroke="#b9964c" stroke-width="4"/>':''}`,`Canal rescue: ${['Duck waiting on the bank','Duck aboard the parcel boat','Water lifted the boat to the upper canal','Gate open; Duck and the parcel reach the other side'][p.step]}`);}
 function canalView(p){return `${canal(p)}<div class="pp-story-strip">${['Duck has a parcel for a friend. First, help Duck get aboard.','Duck is aboard! Raise the water so the boat reaches the upper canal.','The boat is high enough. Open the gate to reach our friend.','Duck and the parcel arrived safely!'][p.step]}</div>${p.step<3?`<button class="primary pp-big-action" id="ppAction">${['Lower the boarding ramp','Pump water into the lock','Open the canal gate'][p.step]}</button><p class="pp-small">One comfortable control. Every press changes the rescue.</p>`:''}`;}
 function workshop(p){return svg(`<rect width="700" height="400" rx="24" fill="#eee6d8"/><path d="M0 334H700V400H0Z" fill="#cba983"/><rect x="66" y="35" width="570" height="48" rx="12" fill="#d5c49f"/><path d="M100 57H600" stroke="#b09b73" stroke-width="4"/><path d="M135 152Q135 129 157 129H489Q537 129 556 191V288H135Z" fill="${p.paint}" stroke="#436271" stroke-width="4"/><rect x="159" y="150" width="79" height="65" rx="9" fill="#d8edf1"/><rect x="253" y="150" width="79" height="65" rx="9" fill="#d8edf1"/><rect x="347" y="150" width="79" height="65" rx="9" fill="#d8edf1"/><path d="M448 150H484Q508 150 521 190H448Z" fill="#d8edf1"/><path d="M133 242H558" stroke="#f9dc8b" stroke-width="13"/>${p.wheels.map((v,i)=>`<circle cx="${218+i*244}" cy="289" r="37" fill="${v?'#354e5b':'#d2bea0'}" stroke="#546878" stroke-width="4" ${v?'':'stroke-dasharray="8 7"'}/>${v?`<circle cx="${218+i*244}" cy="289" r="15" fill="#bfd3d5"/>`:''}`).join('')}${p.washed?'':'<g fill="#9b8268" opacity=".8"><ellipse cx="189" cy="176" rx="22" ry="12"/><ellipse cx="293" cy="193" rx="22" ry="11"/><ellipse cx="385" cy="168" rx="17" ry="12"/></g>'}${p.horn?'<path d="M569 125l26-12M581 151h26M576 177l24 14" stroke="#b38140" stroke-width="6" stroke-linecap="round"/>':''}<path d="M105 337H593" stroke="#8f7559" stroke-width="5"/>`,`${p.wheels.filter(Boolean).length} wheels fitted; windows ${p.washed?'clean':'muddy'}; ${p.horn?'visual horn marks':''}`);}
 const tools=[['wheel','Wheel'],['sponge','Sponge'],['paint','Paint'],['horn','Horn']];
 function toolArt(id){return id==='sponge'?svg('<rect x="205" y="100" width="290" height="190" rx="40" fill="#efca60"/><g fill="#c6983f"><circle cx="255" cy="145" r="12"/><circle cx="375" cy="245" r="10"/><circle cx="425" cy="148" r="14"/></g>','A sponge'):id==='paint'?svg('<path d="M280 185H420L390 330H310Z" fill="#cd9b68"/><path d="M295 185V76H405V185Z" fill="#7b9ec0"/>','Paintbrush'):id==='horn'?svg('<path d="M260 164L440 93V307L260 236Z" fill="#e3b957"/><ellipse cx="253" cy="200" rx="40" ry="57" fill="#566e7b"/>','A toy horn'):svg('<circle cx="350" cy="200" r="145" fill="#354e5b"/><circle cx="350" cy="200" r="65" fill="#c1d5d4"/>','A wheel');}
 function workshopView(p){return `<div class="pp-workshop pp-board" data-pp-part="body">${workshop(p)}${!p.finished?`<button data-pp-part="wheel0" class="pp-part pp-wheel0" aria-label="Fit a wheel in the left wheel space"></button><button data-pp-part="wheel1" class="pp-part pp-wheel1" aria-label="Fit a wheel in the right wheel space"></button><button data-pp-part="window" class="pp-part pp-window" aria-label="Clean the bus windows"></button>`:''}</div><div class="pp-goals"><span>${p.wheels.filter(Boolean).length}/2 wheels</span><span>${p.washed?'✓ Windows clean':'○ Clean the windows'}</span></div>${!p.finished?`<p class="pp-story-strip">The toy bus has two missing wheels and muddy windows. Fix it for the parade! Paint and a pretend horn are yours to try, too.</p><div class="pp-tools">${tools.map(([id,name])=>`<button data-pp-tool="${id}" aria-pressed="${p.selected===id}" class="${p.selected===id?'selected':''}">${toolArt(id)}<span>${name}</span></button>`).join('')}</div><p class="pp-small">Drag a wheel, sponge or paintbrush onto the bus. Or tap the tool, then the part. The horn works when tapped.</p>`:''}`;}
 function repair(s,tool,part){if(!can(s))return;const p=s.play;if(tool==='wheel'&&part.startsWith('wheel')){const i=+part.at(-1);if(p.wheels[i])return change(s,'That wheel is already fitted. Try the other space.');p.wheels[i]=true;}else if(tool==='sponge'&&part==='window')p.washed=true;else if(tool==='paint'&&part==='body')p.paint=p.paint==='#779cc2'?'#b285a5':p.paint==='#b285a5'?'#c99a54':'#779cc2';else return change(s,'That tool has a different job. Wheels fit the round spaces; the sponge cleans the windows.');p.selected=null;if(p.wheels.every(Boolean)&&p.washed)finish(s,'Parade ready! You repaired the bus.');else change(s,tool==='wheel'?'A wheel clicks into place!':tool==='sponge'?'Sparkling windows!':'A new colour for your bus.');}
 function connections(pipe){const dirs=pipe.type==='straight'?[0,2]:[0,1];return dirs.map(d=>(d+pipe.r)%4);}
 function trace(p){let cell=0,entry=3;const visited=new Set(),points=[];while(!visited.has(cell)){visited.add(cell);const piece=p.pipes.find(v=>v.cell===cell);if(!piece||!connections(piece).includes(entry))return{ok:false,points,at:cell};points.push(cell);const exit=connections(piece).find(v=>v!==entry),row=Math.floor(cell/3),col=cell%3;if(exit===1&&col===2)return{ok:row===1,points,at:cell};const nr=row+([0,0,1,0][exit]||0)-(exit===0?1:0),nc=col+(exit===1?1:exit===3?-1:0);if(nr<0||nr>1||nc<0||nc>2)return{ok:false,points,at:cell};cell=nr*3+nc;entry=(exit+2)%4;}return{ok:false,points,at:cell};}
 const cx=cell=>145+(cell%3)*150,cy=cell=>105+Math.floor(cell/3)*150;
 function marble(p){const t=p.trace.length?p.trace.at(-1):null;return svg(`<rect width="700" height="400" rx="24" fill="#e1ebed"/><path d="M0 351H700V400H0Z" fill="#d0bc98"/><path d="M25 105H70" stroke="#bda576" stroke-width="22"/>${p.pipes.map(piece=>{const x=cx(piece.cell),y=cy(piece.cell),d=piece.type==='straight'?'M0-75V75':'M0-75V0H75';return `<g transform="translate(${x} ${y})"><rect x="-73" y="-73" width="146" height="146" rx="16" fill="#fff8e5" stroke="#c5b99a" stroke-width="3"/><path d="${d}" transform="rotate(${piece.r*90})" fill="none" stroke="#83a9a5" stroke-width="26" stroke-linecap="round"/><path d="${d}" transform="rotate(${piece.r*90})" fill="none" stroke="#d6e8dc" stroke-width="10" stroke-linecap="round"/></g>`;}).join('')}<path d="M520 255H625" stroke="#bda576" stroke-width="22"/><path d="M620 293V202H658V293" fill="none" stroke="#a5835d" stroke-width="7"/><path d="M621 223q19-47 38 0l8 19h-53Z" fill="#e1b44d" stroke="#a47b34" stroke-width="3"/><circle cx="641" cy="247" r="7" fill="#9b793f"/><circle cx="${p.finished?635:t===null?43:cx(t)}" cy="${p.finished?255:t===null?105:cy(t)}" r="15" fill="#ba6c91" stroke="#79455e" stroke-width="3"/>${p.finished?'<path d="M601 208l-11-12M679 210l11-12M639 183v-15" stroke="#b58c3d" stroke-width="4"/>':''}`,'Marble machine. Join the tubes from the entrance on the left to the bell on the lower right.');}
 function marbleView(p){return `<p class="pp-story-strip">The marble wants to ring the bell. Turn the tubes to make a connected path.</p><div class="pp-marble pp-board">${marble(p)}${!p.finished?p.pipes.filter(v=>v.cell!==0).map(v=>`<button class="pp-pipe" data-pp-pipe="${v.cell}" style="left:${(cx(v.cell)-72)/7}%;top:${(cy(v.cell)-72)/4}%;" aria-label="Turn tube ${v.cell}. Current connections ${connections(v).map(d=>['top','right','bottom','left'][d]).join(' and ')}"><span>↻ Turn</span></button>`).join(''):''}</div>${!p.finished?'<div class="pp-marble-controls"><button class="secondary" id="ppTest">Try the marble</button><button id="ppBall" class="pp-ball" aria-label="Marble; drag to the entrance to test the path">●</button><span id="ppEntrance" class="pp-entrance">Start here</span></div><p class="pp-small">Tap a tube to turn it. The marble tests the completed route automatically. Drag the spare marble to Start here to try an unfinished route.</p>':''}`;}
 function turn(s,cell){if(!can(s))return;const p=s.play,v=p.pipes.find(v=>v.cell===cell);if(!v||cell===0)return;v.r=(v.r+1)%4;p.trace=[];const t=trace(p);if(t.ok){p.trace=t.points;finish(s,'Ding! Your path carried the marble all the way to the bell.');}else change(s,'The tube turned. Follow the openings from the entrance.',`[data-pp-pipe="${cell}"]`);}
 function tripScene(p){const d=p.destination,step=p.step;let background='<rect width="700" height="400" rx="24" fill="#dceef2"/><circle cx="600" cy="52" r="28" fill="#ffe3a0"/>';if(d==='moon')background='<rect width="700" height="400" rx="24" fill="#465775"/><g fill="#fff1b7"><circle cx="99" cy="69" r="4"/><circle cx="357" cy="43" r="5"/><circle cx="564" cy="94" r="4"/></g><circle cx="600" cy="55" r="29" fill="#ccdecc"/>';
 let body=background+`<path d="M0 294Q240 248 700 285V400H0Z" fill="${d==='beach'?'#e7c993':d==='moon'?'#bdc2cd':'#b6cf9c'}"/>`;
 if(!d)return svg(body+`<path d="M0 337H700" stroke="#c5ab83" stroke-width="50"/>${readingAdventureVan().replace(/^<svg[^>]*>/,'<svg x="240" y="145" width="220" height="150" viewBox="0 0 230 145">')}${person(75,197)}`,'The adventure bus is ready for your destination.');
 if(d==='beach'){body+='<path d="M0 180Q140 160 270 183V285H0Z" fill="#83c2cf"/>';body+=step===0?'<path d="M342 242H423L412 295H353Z" fill="#bf809d"/><path d="M341 241q42-38 83 0" fill="none" stroke="#a96c89" stroke-width="6"/>':'<path d="M334 293V229H425V293M353 229V211H370V229M390 229V211H407V229" fill="#c6a16a" stroke="#a5804f" stroke-width="4"/>';if(step>=2)body+='<path d="M381 210V153L430 166L381 183" fill="#96749f" stroke="#866b50" stroke-width="4"/>';}
 if(d==='forest'){body+='<path d="M84 270V120M583 270V108" stroke="#aa845d" stroke-width="20"/><g fill="#79a07a"><circle cx="84" cy="104" r="60"/><circle cx="583" cy="99" r="67"/></g>';body+=step===0?'<ellipse cx="359" cy="294" rx="51" ry="14" fill="#aa8963"/>':`<path d="M360 296V${step===1?261:197}" stroke="#73974d" stroke-width="8"/><path d="M360 276q-45-30-43-4q18 23 43 10" fill="#8aa95b"/>${step>=2?'<g fill="#ecc46b"><circle cx="360" cy="182" r="28"/><circle cx="337" cy="202" r="28"/><circle cx="384" cy="203" r="28"/></g><circle cx="360" cy="202" r="20" fill="#a47a46"/>':''}`;}
 if(d==='moon'){body+=`<g transform="${step===1?'translate(150 -105)':'translate(0 0)'}"><path d="M332 294V218Q360 168 388 218V294Z" fill="#e5ddc5" stroke="#8497aa" stroke-width="4"/><circle cx="360" cy="232" r="18" fill="#83b4c3"/>${step===1?'<path d="M342 303l17 39 18-39" fill="#e6b25d"/>':''}</g>`;if(step<2)body+=`<svg x="${step===1?485:487}" y="${step===1?93:125}" width="${step===1?50:75}" height="${step===1?55:85}" viewBox="0 -20 200 220">${readingAdventureAnimal('bear').replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</svg>`;else body+=person(437,200,'bear');}
 body+=person(140,196,'duck',step===2?'bounce':'wave');return svg(body,`${d} adventure: step ${step+1}`);}
 const trips={beach:{name:'Beach',object:'bucket',prompts:['Turn the sand bucket over to make a castle.','Give your sandcastle a flag.'],actions:['Turn over the sand bucket','Add a flag']},forest:{name:'Forest',object:'tree',prompts:['Plant a pretend seed in the soft earth.','Water the seed. Our make-believe flower will grow!'],actions:['Plant the seed','Water the seed']},moon:{name:'Moon',object:'rocket',prompts:['Teddy is floating above the moon! Send the rescue rocket.','Bring Teddy gently down to the moon.'],actions:['Launch the rescue rocket','Land with Teddy']}};
 function tripView(p){return `${tripScene(p)}${!p.destination?`<p class="pp-story-strip">Where shall the adventure bus take us? Your choice opens a different little story.</p><div class="pp-destinations">${Object.entries(trips).map(([id,d])=>`<button data-pp-trip="${id}">${readingPicture(d.object)}<b>${d.name}</b></button>`).join('')}</div>`:p.finished?'':`<p class="pp-story-strip">${trips[p.destination].prompts[p.step]}</p><button class="primary pp-big-action" id="ppAction">${trips[p.destination].actions[p.step]}</button><button class="back" id="ppMap">Choose a different destination</button>`}`;}
 function cover(id){const p={step:0,wheels:[false,true],paint:'#779cc2',washed:false,pipes:[{cell:0,type:'straight',r:1},{cell:1,type:'elbow',r:2},{cell:4,type:'elbow',r:0},{cell:5,type:'straight',r:1}],trace:[],destination:null};return id==='canal'?canal(p):id==='workshop'?workshop(p):id==='marble'?marble(p):tripScene(p);}
 function render(focus){const s=senState;init(s);const p=s.play,g=supportPathways[s.key].games[s.index];senShell(`<div class="purposeful-play" data-mission="${p.id}" ${paused?'data-paused="true"':''}><h1>${senEscape(g.title)}</h1><p class="pp-intro">${senEscape(g.invitation)}</p><div class="pp-game" ${paused?'inert':''}>${p.id==='canal'?canalView(p):p.id==='workshop'?workshopView(p):p.id==='marble'?marbleView(p):tripView(p)}</div><p class="feedback" role="status" aria-live="polite">${senEscape(s.response)}</p>${paused?'<p role="status">Paused. Resume when you are ready.</p>':''}${s.done&&(typeof CourseFlow==='undefined'||!CourseFlow.enabled)?'<button class="primary" id="ppContinue">Next activity →</button>':''}<button class="back" id="ppPause">${paused?'Resume':'Pause'}</button><details class="quiet-notes"><summary>For grown-ups · what this supports</summary><p>${senEscape(g.skill)}</p><p>${senEscape(g.tip)}</p><p>Play together. An adult can read, model, or enter the child’s choice. Pointing, signs, AAC and speech are welcome. This records participation, not independent reading or treatment benefit.</p></details></div>`);
 const version=p.version;const valid=()=>can(s)&&s.play.version===version;const bind=(el,d)=>{if(el&&typeof TouchPlay!=='undefined')TouchPlay.bind(el,{...d,drop:target=>{if(valid())d.drop(target);}});};const click=(selector,fn)=>q(selector)?.addEventListener('click',()=>{if(valid())fn();});
 click('#ppAction',()=>{p.step++;if(p.id==='canal'&&p.step===3)finish(s,'Special delivery! Duck and the parcel reached their friend.');else if(p.id==='trip'&&p.step===2)finish(s,p.destination==='beach'?'A castle fit for a very small king!':p.destination==='forest'?'A flower for the forest friends!':'Teddy is safely back on the moon!');else change(s,'Look what changed!','#ppAction');});
 q('#ppPause').onclick=()=>{if(!active(s))return;if(skillContext)CourseFlow.setPaused(!paused);else pause(!paused);};q('#ppContinue')?.addEventListener('click',()=>continueCourse(s));
 q('#ppMap')?.addEventListener('click',()=>{if(!valid())return;p.destination=null;p.step=0;change(s,'Choose where the story goes next.','[data-pp-trip]');});
 app.querySelectorAll('[data-pp-trip]').forEach(el=>el.onclick=()=>{if(!valid())return;p.destination=el.dataset.ppTrip;p.step=0;change(s,`We arrived at the ${p.destination}!`,'#ppAction');});
 app.querySelectorAll('[data-pp-tool]').forEach(el=>{const tool=el.dataset.ppTool;el.onclick=()=>{if(!valid())return;if(tool==='paint'){repair(s,'paint','body');}else if(tool==='horn'){p.horn=!p.horn;change(s,p.horn?'PARP! A pretend horn for the parade.':'The horn rests. What needs fixing?','[data-pp-tool="horn"]');}else{p.selected=tool;change(s,`Choose where the ${tool} should go.`,'[data-pp-part]');}};bind(el,{targets:()=>[...app.querySelectorAll('[data-pp-part]')],drop:target=>repair(s,tool,tool==='paint'?'body':target.dataset.ppPart)});});
 app.querySelectorAll('[data-pp-part]').forEach(el=>el.onclick=()=>{if(!valid())return;if(p.selected)repair(s,p.selected,el.dataset.ppPart);else change(s,'Pick a tool, then the part you want to repair.','[data-pp-tool]');});
 app.querySelectorAll('[data-pp-pipe]').forEach(el=>el.onclick=()=>{if(valid())turn(s,+el.dataset.ppPipe);});const test=()=>{const t=trace(p);p.trace=t.points;if(t.ok)finish(s,'Ding! Your marble rang the bell.');else{s.retries++;change(s,'The marble stops at the gap. Turn a tube to connect its openings.','#ppTest');}};click('#ppTest',test);bind(q('#ppBall'),{targets:()=>[q('#ppEntrance')],drop:test});
 if(focus)q(focus)?.focus({preventScroll:true});if(typeof CourseFlow!=='undefined')CourseFlow.refresh();if(s.done)schedule(s);
 }
 function pause(value){paused=value;if(senState?.play)senState.play.version=++serial;cancel();if(senState?.task?.mode==='mission'&&active(senState))render();}
 function migrate(){try{if(localStorage.getItem('spotmatch-purposeful-retirement-v1'))return;for(const [key,path]of Object.entries(supportPathways))for(let i=0;i<path.games.length;i++)if(path.games[i].kind==='mission'){if(senProgress[key])delete senProgress[key][i];for(const skill of learningSkills)for(const course of skill.courses)course.activities.forEach((a,index)=>{if(a.engine==='support'&&a.key===key&&a.index===i&&skillNotes[course.id]?.activities)delete skillNotes[course.id].activities[index];});}senSave();skillSave();localStorage.setItem('spotmatch-purposeful-retirement-v1','true');}catch{}}
 return{render,cover,pause,trace,connections,cancel,migrate};
})();
